50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	const CURSE_SURCHARGE_PERCENT = 50;
53	
54	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	/** Percentages are applied as integer arithmetic so that the final
64	 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
65	const addPercent = (amount: number, percent: number): number =>
66	  amount + (amount * percent) / 100;
67	
68	/** Rounds up — premiums round in the MHPCO's favour. */
69	const roundPremium = (amount: number): number => Math.ceil(amount);
70	
71	const COMPONENT_BLOCK_SIZE = 3;
72	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
73	
74	const COMPONENT_TYPES = ["rune", "moonstone"];
75	
76	const isComponent = (item: Item): boolean =>
77	  COMPONENT_TYPES.includes(item.type);
78	
79	const itemBasePremium = (item: Item): number =>
80	  BASE_PREMIUM_BY_TYPE[item.type];
81	
82	const countByType = (items: Item[]): Map<string, number> => {
83	  const counts = new Map<string, number>();
84	  for (const item of items) {
85	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
86	  }
87	  return counts;
88	};
89	
90	/** A block is exactly three alike components, priced as a unit rather than
91	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
92	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
93	  count === COMPONENT_BLOCK_SIZE
94	    ? COMPONENT_BLOCK_BASE_PREMIUM
95	    : count * BASE_PREMIUM_BY_TYPE[type];
96	
97	const sum = (amounts: number[]): number =>
98	  amounts.reduce((total, amount) => total + amount, 0);
99	
100	const policyBasePremium = (items: Item[]): number => {
101	  const mainItems = items.filter((item) => !isComponent(item));
102	  const componentGroups = [...countByType(items.filter(isComponent))];
103	
104	  return (
105	    sum(mainItems.map(itemBasePremium)) +
106	    sum(componentGroups.map(componentGroupBasePremium))
107	  );
108	};
109	
110	/** Item-scoped surcharges apply to the affected item's own base premium,
111	 *  not to the policy total. */
112	const itemSurcharges = (item: Item): number =>
113	  item.cursed ? (itemBasePremium(item) * CURSE_SURCHARGE_PERCENT) / 100 : 0;
114	
115	const quote = (items: Item[]): QuoteResult => {
116	  const basePremium = policyBasePremium(items);
117	  // Item-scoped surcharges and policy-wide modifiers are both computed
118	  // against the policy base premium, then added to it.
119	  const firstInsurance = (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100;
120	  const modifiedPremium =
121	    basePremium + sum(items.map(itemSurcharges)) + firstInsurance;
122	  // The processing fee is added last, after all percentage modifiers.
123	  const premium = modifiedPremium + PROCESSING_FEE;
124	  return { premium: roundPremium(premium) };
125	};
126	
127	const runStep = (step: Step): StepResult => {
128	  if (step.op === "quote") return quote(step.items);
129	  throw new Error(`Unsupported step: ${step.op}`);
130	};
131	
132	export const runScenario = (scenario: Scenario): ScenarioResult => {
133	  const results = scenario.steps.map(runStep);
134	  return { results };
135	};
